package com.playsphere.report;import com.playsphere.audit.AuditService;import com.playsphere.common.*;import com.playsphere.user.CurrentUserService;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.List;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class ReportController{private final ReportRepository repo;private final CurrentUserService current;private final AuditService audit;public ReportController(ReportRepository r,CurrentUserService c,AuditService a){repo=r;current=c;audit=a;}public record CreateReport(@NotBlank String targetType,@NotBlank String targetId,@NotBlank @Size(max=120)String reason,@NotBlank @Size(max=1000)String description,@Pattern(regexp="LOW|MEDIUM|HIGH|URGENT")String priority){}public record ResolveReport(@Pattern(regexp="RESOLVED|REJECTED|ESCALATED")String status,@NotBlank @Size(max=1000)String note){}@PostMapping("/reports")public ApiResponse<Report> create(@Valid @RequestBody CreateReport r,Authentication a){return ApiResponse.ok("Report submitted",repo.save(new Report(current.require(a).getId(),r)));}@GetMapping("/reports/mine")public ApiResponse<List<Report>> mine(Authentication a){return ApiResponse.ok("My reports",repo.findByReporterUserIdOrderByCreatedAtDesc(current.require(a).getId()));}@GetMapping("/admin/reports")@PreAuthorize("hasAnyRole('ADMIN','SUPER_ADMIN')")public ApiResponse<List<Report>> queue(){return ApiResponse.ok("Open reports",repo.findByStatusOrderByCreatedAtAsc("OPEN"));}@PatchMapping("/admin/reports/{id}")@PreAuthorize("hasAnyRole('ADMIN','SUPER_ADMIN')")public ApiResponse<Report> resolve(@PathVariable String id,@Valid @RequestBody ResolveReport r,Authentication a){String admin=current.require(a).getId();Report report=repo.findById(id).orElseThrow(()->new BusinessException(HttpStatus.NOT_FOUND,"Report not found"));report.resolve(admin,r.status(),r.note());audit.record(admin,"REPORT_"+r.status(),"REPORT",id,r.note());return ApiResponse.ok("Report updated",repo.save(report));}}
